class TestConversationComponent(BloomerpComponentTestCase):
    """Exercise reusable thread rendering and the membership boundary."""

    view_name = "components_conversation"

    def prepare_conversation(self, scenario: RequestScenario) -> None:
        """Create an authorized conversation with a quote, reaction and child reply."""
        connection = None
        self.chat = IMConversation.objects.create(
            connection=connection, name="Project conversation"
        )
        self.member = IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.normal_user
        )
        self.root = IMMessage.objects.create(
            conversation=self.chat,
            sender=self.member,
            sequence=1,
            body="<script>unsafe</script>",
        )
        self.quoted = IMMessage.objects.create(
            conversation=self.chat,
            sender=self.member,
            sequence=2,
            body="Quoted response",
            reply_to=self.root,
        )
        self.reply = IMMessage.objects.create(
            conversation=self.chat,
            sender=self.member,
            sequence=3,
            body="Child reply content",
            thread_root=self.root,
        )
        IMMessageReaction.objects.create(
            message=self.root, participant=self.member, emoji="👍🏽"
        )
        scenario.view_kwargs = {"conversation_id": self.chat.pk}

    def prepare_thread(self, scenario: RequestScenario) -> None:
        """Select a root and show only its thread messages."""
        self.prepare_conversation(scenario)
        scenario.query_params = {"thread": str(self.root.pk)}

    def prepare_left(self, scenario: RequestScenario) -> None:
        """Revoke membership before requesting the private fragment."""
        self.prepare_conversation(scenario)
        self.member.left_at = timezone.now()
        self.member.save()

    def prepare_deleted(self, scenario: RequestScenario) -> None:
        """Ensure deleted text cannot leak through quoted message previews."""
        self.prepare_conversation(scenario)
        self.root.deleted_at = timezone.now()
        self.root.save()

    def prepare_foreign_thread(self, scenario: RequestScenario) -> None:
        """Reject a root belonging to another conversation."""
        self.prepare_conversation(scenario)
        other = IMConversation.objects.create(connection=self.chat.connection)
        member = IMConversationParticipant.objects.create(
            conversation=other, user=self.normal_user
        )
        root = IMMessage.objects.create(
            conversation=other, sender=member, sequence=1, body="Secret foreign root"
        )
        scenario.query_params = {"thread": str(root.pk)}

    def prepare_object_tag(self, scenario: RequestScenario) -> None:
        """Store an object tag with a forged URL to exercise reader-side resolution."""
        self.prepare_conversation(scenario)
        IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.admin_user
        )
        content_type = ContentType.objects.get_for_model(self.admin_user)
        self.root.body_html = f'<p><span data-reference-kind="object" data-target-id="{self.admin_user.pk}" data-target-content-type-id="{content_type.pk}" data-reference-url="https://forged.invalid/">Tagged user</span></p>'
        self.root.save()

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover rendering, escaping, isolation, methods and denied membership."""
        return [
            RequestScenario(
                name="Readable object tags receive canonical links",
                user=self.admin_user,
                prepare=self.prepare_object_tag,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text('data-reference-url="/'),
                        self.does_not_contain_text("forged.invalid"),
                    ]
                ),
            ),
            RequestScenario(
                name="Unreadable object tags retain only their label",
                user=self.normal_user,
                prepare=self.prepare_object_tag,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Tagged user"),
                        self.does_not_contain_text("data-reference-url"),
                        self.does_not_contain_text('data-reference-kind="object"'),
                    ]
                ),
            ),
            RequestScenario(
                name="Member sees timeline and editor without shell back button",
                user=self.normal_user,
                prepare=self.prepare_conversation,
                expected=ExpectedResult(
                    status_code=200,
                    response_validators=[
                        self.contains_text("Quoted response"),
                        self.contains_text("👍🏽"),
                        self.contains_text("bloomerp-text-editor"),
                        self.contains_text("&lt;script&gt;unsafe&lt;/script&gt;"),
                        self.does_not_contain_text("Child reply content"),
                        self.does_not_contain_text('data-action="back"'),
                        self.header_equals("Cache-Control", "private, no-store"),
                    ],
                ),
            ),
            RequestScenario(
                name="Root thread loads separately",
                user=self.normal_user,
                prepare=self.prepare_thread,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Child reply content"),
                        self.does_not_contain_text("Quoted response"),
                    ]
                ),
            ),
            RequestScenario(
                name="Deleted body and quote are hidden",
                user=self.normal_user,
                prepare=self.prepare_deleted,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Message deleted"),
                        self.does_not_contain_text("unsafe"),
                    ]
                ),
            ),
            RequestScenario(
                name="Former member denied",
                user=self.normal_user,
                prepare=self.prepare_left,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Superuser does not bypass private membership",
                user=self.admin_user,
                prepare=self.prepare_conversation,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Anonymous login required",
                prepare=self.prepare_conversation,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Foreign thread denied",
                user=self.normal_user,
                prepare=self.prepare_foreign_thread,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Malformed thread rejected",
                user=self.normal_user,
                prepare=self.prepare_conversation,
                query_params={"thread": "bad"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Missing conversation",
                user=self.normal_user,
                view_kwargs={"conversation_id": uuid4()},
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Loading cannot post messages",
                user=self.normal_user,
                method="POST",
                prepare=self.prepare_conversation,
                expected=ExpectedResult(status_code=405),
            ),
        ]


def audio_call_capabilities(
    user: AbstractBloomerpUser, chat: IMConversation
) -> IMCallCapabilities:
    """Supply a non-native provider's limited call capabilities."""
    return IMCallCapabilities(audio=True)


class TestConversationCalling(CallFixtures, BloomerpComponentTestCase):
    """Prove browser actions are driven by provider declarations."""

    view_name = "components_conversation"

    def prepare_browser_call(self, scenario: RequestScenario) -> None:
        """Render an invited session alongside provider-declared start controls."""
        self.prepare_session()
        scenario.view_kwargs = {"conversation_id": self.chat.pk}

    def prepare_alternate_provider(self, scenario: RequestScenario) -> None:
        """Use another provider identity with audio-only calling hooks."""
        self.prepare_browser_call(scenario)
        provider = IM_PROVIDER_REGISTRY.get("internal")
        alternate = replace(
            provider,
            key="alternate",
            calling=replace(
                provider.calling, capabilities_resolver=audio_call_capabilities
            ),
        )
        self.provider_patch = patch.dict(
            IM_PROVIDER_REGISTRY._registry, {"alternate": alternate}
        )
        self.identity_patch = patch.object(
            IMConversation,
            "provider_key",
            new_callable=PropertyMock,
            return_value="alternate",
        )
        self.provider_patch.start()
        self.identity_patch.start()
        scenario.cleanup = self.restore_provider

    def restore_provider(self, scenario: RequestScenario) -> None:
        """Restore the registry and model descriptor after each scenario."""
        self.identity_patch.stop()
        self.provider_patch.stop()

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover declared video, alternate audio-only providers and timeline admission."""
        return [
            RequestScenario(
                name="Declared provider renders audio video and session join",
                user=self.normal_user,
                prepare=self.prepare_browser_call,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text('data-media-mode="audio"'),
                        self.contains_text('data-media-mode="video"'),
                        self.contains_text('data-call-action="join"'),
                    ]
                ),
            ),
            RequestScenario(
                name="Alternate provider controls audio-only buttons",
                user=self.normal_user,
                prepare=self.prepare_alternate_provider,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text('data-media-mode="audio"'),
                        self.does_not_contain_text('data-media-mode="video"'),
                    ]
                ),
            ),
        ]
